Regional Ingress.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(regional_ingress, "Regional Ingress") {
    Component(GCP_Cloud_Armor, "GCP Cloud Armor", "Google Cloud Platform", "Provides edge-level DDoS defense, adaptive rate limiting, and geo-detection.")
    Component(Global_External_HTTPS_Load_Balancer, "Global External HTTP(S) Load Balancer", "GCP Load Balancing", "Forwards incoming TCP/HTTPS streams via internal VPC to the edge proxy.")
    Component(Envoy_Edge_Proxy, "Envoy Edge Proxy", "Envoy", "Handles TLS 1.3 termination, WebSocket upgrades, and traffic routing.")
    Component(Envoy_WASM_Route_Policy_Enforcer, "Envoy WASM Route & Policy Enforcer", "WASM Extension", "Invokes in-process synchronous inspection, custom policy enforcement, JWT validation, and geo-pinning.")
}

Rel(Global_External_HTTPS_Load_Balancer, Envoy_Edge_Proxy, "Forwards TCP/HTTPS streams via internal VPC", "TCP/HTTPS")
Rel(Envoy_Edge_Proxy, Envoy_WASM_Route_Policy_Enforcer, "Invokes in-process synchronous inspection", "In-process")
Rel(Envoy_WASM_Route_Policy_Enforcer, Downstream_Containers, "Routes verified traffic via gRPC and mTLS (SPIFFE/SPIRE)", "gRPC / mTLS")

@enduml

AI Orchestrator & Audit Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the AI Orchestrator & Audit Service container

Container_Boundary(ai_orchestrator_audit_service, "AI Orchestrator & Audit Service") {
    Component(AI_Orchestrator, "AI Orchestrator", "Python / FastAPI", "Orchestrates interactions with the AI symptom checker engine and telehealth services.")
    Component(Audit_Service, "Audit Service", "Python / FastAPI", "Handles encrypted audit writes and asynchronous audit ingestion.")
}

Rel(AI_Orchestrator, Audit_Service, "Sends audit logs for encrypted writing via Cloud KMS", "Internal")

@enduml

Consent & Identity Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(consent_identity_service, "Consent & Identity Service") {
    Component(Authentication_Engine, "Authentication Engine", "Keycloak", "Handles user authentication, OAuth2/OIDC protocols, and issues short-lived tokens.")
    Component(Consent_Management_Module, "Consent Management Module", "Keycloak Custom SPI", "Manages purpose-based GDPR and HIPAA consent records.")
    Component(Identity_Database, "Identity Database", "PostgreSQL (Cloud SQL)", "Persists user identity profiles, credentials, and consent data.")
    Component(Token_Cache, "Token Cache", "Redis (Memorystore)", "Provides low-latency token caching and revocation checks.")
}

Rel(Authentication_Engine, Identity_Database, "Queries and updates user and consent data", "JDBC / SQL")
Rel(Authentication_Engine, Token_Cache, "Checks token validity and revocation status", "Redis Protocol")
Rel(Consent_Management_Module, Identity_Database, "Stores and retrieves consent preferences", "JDBC / SQL")
@enduml
